-- ============================================================
-- USUARIOS
-- ============================================================
CREATE TABLE IF NOT EXISTS "Usuarios" (
  "id"          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre"      varchar(100) NOT NULL,
  "email"       varchar(150) NOT NULL UNIQUE,
  "telefono"    varchar(30),
  "rol"         varchar(10) NOT NULL DEFAULT 'usuario'
                 CHECK ("rol" IN ('usuario', 'admin')),
  "activo"      boolean NOT NULL DEFAULT true,
  "created_at"  timestamptz NOT NULL DEFAULT now(),
  "updated_at"  timestamptz NOT NULL DEFAULT now()
);

-- ============================================================
-- BILLETERA
-- ============================================================
CREATE TABLE IF NOT EXISTS "Billetera" (
  "id"          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "idUsuario"   integer NOT NULL REFERENCES "Usuarios" ("id") ON DELETE CASCADE,
  "nombre"      varchar(100) NOT NULL,
  "saldo"       numeric(14,2) NOT NULL DEFAULT 0 CHECK ("saldo" >= 0),
  "tipo"        varchar(50) NOT NULL,
  "created_at"  timestamptz NOT NULL DEFAULT now(),
  "updated_at"  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_billetera_usuario ON "Billetera" ("idUsuario");

-- ============================================================
-- CATEGORIA (catálogo opcional)
-- ============================================================
CREATE TABLE IF NOT EXISTS "Categoria" (
  "id"          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre"      varchar(100) NOT NULL UNIQUE,
  "descripcion" varchar(255)
);

-- ============================================================
-- TRANSACCION
-- ============================================================
CREATE TABLE IF NOT EXISTS "Transaccion" (
  "id"           integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "idBilletera"  integer NOT NULL REFERENCES "Billetera" ("id") ON DELETE CASCADE,
  "idCategoria"  integer REFERENCES "Categoria" ("id") ON DELETE SET NULL,
  "monto"        numeric(14,2) NOT NULL CHECK ("monto" > 0),
  "tipo"         varchar(10) NOT NULL CHECK ("tipo" IN ('ingreso', 'egreso')),
  "categoria"    varchar(100) NOT NULL DEFAULT 'otros',
  "fecha"        date NOT NULL,
  "descripcion"  varchar(255),
  "created_at"   timestamptz NOT NULL DEFAULT now(),
  "updated_at"   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_transaccion_billetera ON "Transaccion" ("idBilletera");
CREATE INDEX IF NOT EXISTS idx_transaccion_fecha     ON "Transaccion" ("fecha" DESC);

-- ============================================================
-- TARJETA
-- ============================================================
CREATE TABLE IF NOT EXISTS "Tarjeta" (
  "id"            integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "idUsuario"     integer NOT NULL REFERENCES "Usuarios" ("id") ON DELETE CASCADE,
  "tipo"          varchar(20) NOT NULL CHECK ("tipo" IN ('visa', 'mastercard', 'amex', 'otra')),
  "ultimosCuatro" char(4) NOT NULL CHECK ("ultimosCuatro" ~ '^[0-9]{4}$'),
  "titular"       varchar(100) NOT NULL,
  "vencimiento"   char(5) NOT NULL CHECK ("vencimiento" ~ '^(0[1-9]|1[0-2])/[0-9]{2}$'),
  "activa"        boolean NOT NULL DEFAULT true,
  "created_at"    timestamptz NOT NULL DEFAULT now(),
  "updated_at"    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_tarjeta_usuario ON "Tarjeta" ("idUsuario");

-- ============================================================
-- SUSCRIPCION
-- ============================================================
CREATE TABLE IF NOT EXISTS "Suscripcion" (
  "id"          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "idUsuario"   integer NOT NULL REFERENCES "Usuarios" ("id") ON DELETE CASCADE,
  "idTarjeta"   integer REFERENCES "Tarjeta" ("id") ON DELETE SET NULL,
  "proveedor"   varchar(100) NOT NULL,
  "plan"        varchar(100) NOT NULL,
  "monto"       numeric(14,2) NOT NULL CHECK ("monto" > 0),
  "diaCobro"    smallint NOT NULL CHECK ("diaCobro" BETWEEN 1 AND 31),
  "activa"      boolean NOT NULL DEFAULT true,
  "created_at"  timestamptz NOT NULL DEFAULT now(),
  "updated_at"  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_suscripcion_usuario ON "Suscripcion" ("idUsuario");
CREATE INDEX IF NOT EXISTS idx_suscripcion_tarjeta ON "Suscripcion" ("idTarjeta");

-- ============================================================
-- BOLETA
-- ============================================================
CREATE TABLE IF NOT EXISTS "Boleta" (
  "id"               integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "idUsuario"        integer NOT NULL REFERENCES "Usuarios" ("id") ON DELETE CASCADE,
  "tipoServicio"     varchar(20) NOT NULL
                       CHECK ("tipoServicio" IN ('luz', 'agua', 'gas', 'internet', 'otro')),
  "monto"            numeric(14,2) NOT NULL CHECK ("monto" > 0),
  "fechaVencimiento" date NOT NULL,
  "pagada"           boolean NOT NULL DEFAULT false,
  "fechaPago"        date,
  "created_at"       timestamptz NOT NULL DEFAULT now(),
  "updated_at"       timestamptz NOT NULL DEFAULT now(),
  CHECK ("pagada" = false OR "fechaPago" IS NOT NULL)
);
CREATE INDEX IF NOT EXISTS idx_boleta_usuario     ON "Boleta" ("idUsuario");
CREATE INDEX IF NOT EXISTS idx_boleta_vencimiento ON "Boleta" ("fechaVencimiento");